function RowExpansion({
  caption = "{{caption}}",
  accent = "{{accent}}",
  expand1042 = {{expand1042}},
  expand1041 = {{expand1041}},
  detailContent = "{{detailContent}}",
}) {
  const cell = { padding: "10px 14px", borderBottom: "1px solid #24143020", whiteSpace: "nowrap" };
  const Toggle = ({ open, controls }) => (
    <button type="button" aria-expanded={open} aria-controls={controls} style={{ background: "none", border: 0, cursor: "pointer", padding: 2, display: "inline-flex" }}>
      <span aria-hidden="true" style={{ display: "inline-block", transform: open ? "rotate(90deg)" : "none", transition: "transform .15s", color: accent }}>&#9656;</span>
    </button>
  );
  return (
    <div style={{ maxWidth: 480, borderRadius: 10, border: "1px solid #24143020", overflow: "hidden", font: "14px system-ui, sans-serif", color: "#241430", background: "#FAF7F2" }}>
      <div style={{ overflowX: "auto" }}>
        <table style={{ borderCollapse: "collapse", width: "100%" }}>
          <caption style={{ textAlign: "left", fontWeight: 600, padding: "10px 14px" }}>{caption}</caption>
          <thead>
            <tr style={{ background: accent, color: "#FAF7F2" }}>
              {["", "Order", "Customer", "Total"].map((h, i) => <th key={i} scope="col" style={cell}>{h}</th>)}
            </tr>
          </thead>
          <tbody>
            <tr style={{ borderLeft: expand1042 ? `3px solid ${accent}` : "none" }}>
              <td style={cell}><Toggle open={expand1042} controls="rexp-1042" /></td>
              <td style={cell}>#1042</td><td style={cell}>A. Whitfield</td><td style={cell}>£64.00</td>
            </tr>
            {expand1042 && <tr><td colSpan={4} id="rexp-1042" style={{ background: "#24143008", padding: "8px 14px", fontSize: 13, color: "#241430cc" }}>{detailContent}</td></tr>}
            <tr style={{ borderLeft: expand1041 ? `3px solid ${accent}` : "none" }}>
              <td style={cell}><Toggle open={expand1041} controls="rexp-1041" /></td>
              <td style={cell}>#1041</td><td style={cell}>R. Okafor</td><td style={cell}>£128.50</td>
            </tr>
            {expand1041 && <tr><td colSpan={4} id="rexp-1041" style={{ background: "#24143008", padding: "8px 14px", fontSize: 13, color: "#241430cc" }}>{detailContent}</td></tr>}
            <tr><td style={cell}></td><td style={cell}>#1040</td><td style={cell}>M. Iqbal</td><td style={cell}>£22.00</td></tr>
          </tbody>
        </table>
      </div>
    </div>
  );
}
